<?php $isMentors=$kind==='mentors';$total=$isMentors?$mentorTotal:$experienceTotal; ?>
<header class="discovery-heading"><span class="eyebrow"><?= $this->icon($isMentors?'users':'book') ?><?= $isMentors?'از تجربهٔ دیگران کمک بگیر':'مسیرهای رفته‌شده را بخوان' ?></span><h1><?= $isMentors?'با مرشد آشنا شو':'هر تجربه، آغاز یک گفت‌وگو' ?></h1><p>مسئله‌ات را جست‌وجو کن، تجربه‌های مرتبط را بشناس و با صاحب آن‌ها آشنا شو.</p></header>
<nav class="discovery-tabs" aria-label="نوع جست‌وجو"><?php foreach(['mentors'=>['users','مرشدها',$mentorTotal],'experiences'=>['book','تجربه‌ها',$experienceTotal]] as $tab=>[$icon,$label,$count]): ?><a <?= $kind===$tab?'aria-current="page"':'' ?> href="<?= $this->h($this->url('/'.$tab.'?'.http_build_query(['q'=>$_GET['q']??'','term'=>$_GET['term']??'']))) ?>"><?= $this->icon($icon) ?><span><?= $label ?></span><b><?= (int)$count ?></b></a><?php endforeach; ?></nav>
<div class="discovery-layout"><aside class="discovery-filters"><form method="get" class="card discovery-filter-form"><?php if(!($this->config['pretty_urls']??false)): ?><input type="hidden" name="r" value="/<?= $this->h($kind) ?>"><?php endif; ?><div class="filter-heading"><h2><?= $this->icon('topic') ?>جست‌وجو و فیلتر</h2><span class="small muted">به مسئله‌ات نزدیک‌تر شو</span></div><div class="filter-field discovery-filter-query"><label for="search">دنبال چه تجربه‌ای هستی؟</label><input id="search" type="search" name="q" value="<?= $this->h($_GET['q']??'') ?>" maxlength="160" placeholder="موضوع، مسئله یا نام مرشد"></div><div class="filter-field"><label for="term">موضوع یا مسئله</label><select id="term" name="term"><option value="">همهٔ موضوع‌ها</option><?php foreach($terms as $term): ?><option value="<?= $this->h($term['id']) ?>" <?= ($_GET['term']??'')===$term['id']?'selected':'' ?>><?= $this->h($term['title']) ?></option><?php endforeach; ?></select></div><div class="filter-field"><label for="sort">مرتب‌سازی</label><select id="sort" name="sort"><option value="relevant" <?= ($_GET['sort']??'relevant')==='relevant'?'selected':'' ?>>مرتبط‌ترین</option><option value="latest" <?= ($_GET['sort']??'')==='latest'?'selected':'' ?>>تازه‌ترین</option></select></div><?php if(!$isMentors): ?><details class="discovery-more" <?= !empty($_GET['target_audience'])||!empty($_GET['constraints'])||!empty($_GET['outcome'])?'open':'' ?>><summary>فیلترهای بیشتر</summary><div class="filter-field"><label for="audience">گروه هدف</label><input id="audience" name="target_audience" value="<?= $this->h($_GET['target_audience']??'') ?>" placeholder="مثلاً مدیران فرهنگی"></div><div class="filter-field"><label for="constraints">شرایط و محدودیت مشابه</label><input id="constraints" name="constraints" value="<?= $this->h($_GET['constraints']??'') ?>"></div><div class="filter-field"><label for="outcome">نوع نتیجه</label><select id="outcome" name="outcome"><option value="">همه نتایج</option><?php foreach(['success'=>'موفق','failure'=>'ناموفق','mixed'=>'ترکیبی','unknown'=>'نامشخص'] as $key=>$label): ?><option value="<?= $key ?>" <?= ($_GET['outcome']??'')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div></details><?php endif; ?><div class="discovery-filter-actions"><button class="primary"><?= $this->icon('eye') ?>جست‌وجو</button><a href="<?= $this->h($this->url('/'.$kind)) ?>">پاک کردن فیلترها</a></div></form></aside>
<section class="discovery-results" aria-label="نتایج جست‌وجو"><div class="results-heading"><h2><?= $isMentors?'مرشدها':'تجربه‌های مرتبط' ?></h2><span><?= (int)$total ?> نتیجه</span></div><div class="discovery-grid"><?php foreach(array_slice($rows,0,20) as $row){require __DIR__.($isMentors?'/mentor-card.php':'/experience-card.php');} ?></div><?php if(!$rows): ?><div class="discovery-empty"><?= $this->icon($isMentors?'users':'book') ?><h2>هنوز نتیجه‌ای پیدا نشد</h2><p>عبارت کوتاه‌تری بنویس یا یکی از فیلترها را تغییر بده.</p><a class="secondary" href="<?= $this->h($this->url('/'.$kind)) ?>">دیدن همهٔ <?= $isMentors?'مرشدها':'تجربه‌ها' ?></a></div><?php endif; ?><nav class="row section" aria-label="صفحه‌بندی نتایج"><?php $p=max(1,(int)($_GET['page']??1));$filters=http_build_query(['q'=>$_GET['q']??'','term'=>$_GET['term']??'','target_audience'=>$_GET['target_audience']??'','constraints'=>$_GET['constraints']??'','outcome'=>$_GET['outcome']??'','sort'=>$_GET['sort']??'relevant']);if($p>1): ?><a class="secondary" href="<?= $this->h($this->url('/'.$kind.'?'.$filters.'&page='.($p-1))) ?>">صفحه قبل</a><?php endif;if(count($rows)>20): ?><a class="secondary" href="<?= $this->h($this->url('/'.$kind.'?'.$filters.'&page='.($p+1))) ?>">صفحه بعد</a><?php endif; ?></nav></section></div>
